@Test
void hideUnhide_preservesRecordAndCreationAudit() {
    Rating original = ratingRepository.findAll().stream().filter(r -> r.getProductId().equals(1L)).findFirst().orElseThrow();
    assertEquals(com.yas.rating.model.Visibility.VISIBLE, original.getVisibility());
    var createdOn = original.getCreatedOn();
    var createdBy = original.getCreatedBy();
    RatingVm hidden = ratingService.updateVisibility(original.getId(), com.yas.rating.model.Visibility.HIDDEN);
    assertEquals(com.yas.rating.model.Visibility.HIDDEN, hidden.visibility());
    assertEquals(1, ratingService.getRatingListByProductId(1L, 0, 1).totalElements());
    assertEquals(1, ratingService.getRatingListByProductId(1L, 0, 1).totalPages());
    Rating remaining = ratingRepository.findAll().stream().filter(r -> r.getProductId().equals(1L) && !r.getId().equals(original.getId())).findFirst().orElseThrow();
    assertEquals((double) remaining.getRatingStar(), ratingService.calculateAverageStar(1L));
    assertEquals(2, ratingService.getRatingListWithFilter("product1", "", "", ZonedDateTime.now().minusDays(30), ZonedDateTime.now().plusDays(30), 0, 10).totalElements());
    Rating persisted = ratingRepository.findById(original.getId()).orElseThrow();
    assertEquals(createdOn, persisted.getCreatedOn());
    assertEquals(createdBy, persisted.getCreatedBy());
    assertEquals(original.getContent(), persisted.getContent());
    ratingService.updateVisibility(original.getId(), com.yas.rating.model.Visibility.VISIBLE);
    assertEquals(2, ratingService.getRatingListByProductId(1L, 0, 10).totalElements());
    assertEquals(3.0, ratingService.calculateAverageStar(1L));
}

